    trainable_params, all_param = (0, 0)
    for param in model.parameters():
        num_params = param.numel()
        if num_params == 0 and hasattr(param, 'ds_numel'):
            num_params = param.ds_numel
        if param.__class__.__name__ == 'Params4bit':
