def dump_input_when_exception(exclude_args: Optional[List[int]]=None, exclude_kwargs: Optional[List[str]]=None):

    def _inner(func):

        @wraps(func)
        def _wrapper(*args, **kwargs):
            try:
                return func(*args, **kwargs)
            except Exception as err:
                timestamp = datetime.now().strftime('%Y%m%d-%H%M%S')
                filename = f'/tmp/err_{func.__name__}_input_{timestamp}.pkl'
                logger.info('Writing input of failed execution to %s...', filename)
                with open(filename, 'wb') as filep:
                    dumped_inputs = {k: v for k, v in kwargs.items() if k not in (exclude_kwargs or [])}
                    for i, arg in enumerate(args):
                        if i not in (exclude_args or []):
                            dumped_inputs[f'arg_{i}'] = arg
                    if (kv_caches := dumped_inputs.get('kv_caches')) and isinstance(kv_caches, Iterable):
                        dumped_inputs['kv_caches'] = [(t.dtype, t.shape) for t in kv_caches if is_tensor(t)]
                    try:
                        pickle.dump(dumped_inputs, filep)
                    except Exception as pickle_err:
                        logger.warning('Failed to pickle inputs of failed execution: %s', str(pickle_err))
                        raise type(err)(f'Error in model execution: {str(err)}') from err
                    logger.info('Completed writing input of failed execution to %s.', filename)
                raise type(err)(f'Error in model execution (input dumped to {filename}): {str(err)}') from err
        return _wrapper
    return _inner

class BroadcastableModelInput(ABC):

    @abstractmethod
    def as_broadcastable_tensor_dict(self) -> Dict[str, Any]:
        raise NotImplementedError

    @classmethod
    @abstractmethod
    def from_broadcasted_tensor_dict(cls: Type[T], tensor_dict: Dict[str, Any], attn_backend: Optional['AttentionBackend']=None) -> T:
        raise NotImplementedError

@dataclasses.dataclass(frozen=True)
class ModelRunnerInputBase(BroadcastableModelInput):
    """Local inputs to each worker's model runner. May contain
    device-specific data. Different worker backends may have different methods
    of converting from the global ExecuteModelRequest produced by the LLM
    engine to the worker-local ModelRunnerInputBase objects.

    Model runners that support multi-GPU execution should define a
    ModelRunnerInputBase subclass, add their required fields, and specify how to
    serialize/deserialize a ModelInput for broadcast between workers.
    """
    pass

class ModelRunnerInputBuilderBase(ABC, Generic[T]):
    """A builder to create ModelRunnerInputBase objects.
  """

    @abstractmethod
    def add_seq_group(self, seq_group_metadata):
        raise NotImplementedError

    @abstractmethod
    def build(self, *args, **kwargs) -> T:
        raise NotImplementedError

class ModelRunnerBase(ABC, Generic[T]):
    """
    Model runner interface that abstracts a particular hardware and/or type of
    model. Model execution may communicate data with model runners in other
    processes, but it should not include control plane metadata communication.

    Each ModelRunnerBase subclass should define a corresponding
    ModelRunnerInputBase subclass.
    """
    generators: Dict[str, torch.Generator] = {}

    @abstractmethod
    def make_model_input_from_broadcasted_tensor_dict(self, tensor_dict: Dict[str, Any]) -> T:
        raise NotImplementedError

    @abstractmethod
    def prepare_model_input(self, seq_group_metadata_list: List[SequenceGroupMetadata], virtual_engine: int=0, finished_requests_ids: Optional[List[str]]=None) -> T:
        raise NotImplementedError

    @current_platform.inference_mode()
    def execute_model(self, model_input: T, kv_caches: Optional[List[torch.Tensor]], intermediate_tensors: Optional[IntermediateTensors], num_steps: int=1) -> Optional[List[SamplerOutput]]:
        raise NotImplementedError

    def get_generators(self, finished_request_ids: Optional[List[str]]=None):
        if finished_request_ids:
            for request_id in finished_request_ids:
                self.generators.pop(request_id, None)
        return self.generators

