ModalityStr = Literal['image', 'audio', 'video']
_T = TypeVar('_T')

class BaseMultiModalItemTracker(ABC, Generic[_T]):
    """
    Tracks multi-modal items in a given request and ensures that the number
    of multi-modal items in a given request does not exceed the configured
    maximum per prompt.
    """

    def __init__(self, model_config: ModelConfig, tokenizer: AnyTokenizer):
        super().__init__()
        self._model_config = model_config
        self._tokenizer = tokenizer
        self._allowed_items = model_config.multimodal_config.limit_per_prompt if model_config.multimodal_config else {}
        self._consumed_items = {k: 0 for k in self._allowed_items}
        self._items: List[_T] = []

    @staticmethod
    @lru_cache(maxsize=None)
    def _cached_token_str(tokenizer: AnyTokenizer, token_index: int) -> str:
        return tokenizer.decode(token_index)

    def _placeholder_str(self, modality: ModalityStr, current_count: int) -> Optional[str]:
        hf_config = self._model_config.hf_config
        model_type = hf_config.model_type
        if modality == 'image':
            if model_type == 'phi3_v':
                return f'<|image_{current_count}|>'
            if model_type == 'minicpmv':
                return '(<image>./</image>)'
            if model_type in ('blip-2', 'chatglm', 'fuyu', 'paligemma', 'pixtral'):
                return None
            if model_type == 'qwen':
                return f'Picture {current_count}: <img></img>'
            if model_type.startswith('llava'):
                return self._cached_token_str(self._tokenizer, hf_config.image_token_index)
            if model_type in ('chameleon', 'internvl_chat'):
                return '<image>'
            if model_type == 'mllama':
                return '<|image|>'
            if model_type == 'qwen2_vl':
                return '<|vision_start|><|image_pad|><|vision_end|>'
            raise TypeError(f'Unknown model type: {model_type}')
        elif modality == 'audio':
            if model_type == 'ultravox':
                return '<|reserved_special_token_0|>'
            raise TypeError(f'Unknown model type: {model_type}')
        elif modality == 'video':
            if model_type == 'qwen2_vl':
                return '<|vision_start|><|video_pad|><|vision_end|>'
            raise TypeError(f'Unknown model type: {model_type}')
        else:
            raise TypeError(f'Unknown modality: {modality}')

    @staticmethod
    def _combine(items: List[MultiModalDataDict]) -> MultiModalDataDict:
        mm_lists: Mapping[str, List[object]] = defaultdict(list)
        for single_mm_data in items:
            for mm_key, mm_item in single_mm_data.items():
                if isinstance(mm_item, list):
                    mm_lists[mm_key].extend(mm_item)
                else:
                    mm_lists[mm_key].append(mm_item)
        return {mm_key: mm_list[0] if len(mm_list) == 1 else mm_list for mm_key, mm_list in mm_lists.items()}

    def add(self, modality: ModalityStr, item: _T) -> Optional[str]:
        allowed_count = self._allowed_items.get(modality, 1)
        current_count = self._consumed_items.get(modality, 0) + 1
        if current_count > allowed_count:
            raise ValueError(f'At most {allowed_count} {modality}(s) may be provided in one request.')
        self._consumed_items[modality] = current_count
        self._items.append(item)
        return self._placeholder_str(modality, current_count)

    @abstractmethod
    def create_parser(self) -> 'BaseMultiModalContentParser':
        raise NotImplementedError

class MultiModalItemTracker(BaseMultiModalItemTracker[MultiModalDataDict]):

    def all_mm_data(self) -> Optional[MultiModalDataDict]:
        return self._combine(self._items) if self._items else None

    def create_parser(self) -> 'BaseMultiModalContentParser':
        return MultiModalContentParser(self)

class AsyncMultiModalItemTracker(BaseMultiModalItemTracker[Awaitable[MultiModalDataDict]]):

    async def all_mm_data(self) -> Optional[MultiModalDataDict]:
        if self._items:
            items = await asyncio.gather(*self._items)
            return self._combine(items)
        return None

    def create_parser(self) -> 'BaseMultiModalContentParser':
        return AsyncMultiModalContentParser(self)

class BaseMultiModalContentParser(ABC):

    def __init__(self) -> None:
