def load_chat_template(chat_template: Optional[Union[Path, str]]) -> Optional[str]:
    if chat_template is None:
        return None
    try:
        with open(chat_template, 'r') as f:
            resolved_chat_template = f.read()
    except OSError as e:
        if isinstance(chat_template, Path):
            raise
        JINJA_CHARS = '{}\n'
        if not any((c in chat_template for c in JINJA_CHARS)):
            msg = f'The supplied chat template ({chat_template}) looks like a file path, but it failed to be opened. Reason: {e}'
            raise ValueError(msg) from e
        resolved_chat_template = codecs.decode(chat_template, 'unicode_escape')
    logger.info('Using supplied chat template:\n%s', resolved_chat_template)
    return resolved_chat_template

def _get_full_multimodal_text_prompt(placeholder_counts: Dict[str, int], text_prompt: str) -> str:
    missing_placeholders: List[str] = []
    for placeholder in placeholder_counts:
        placeholder_counts[placeholder] -= text_prompt.count(placeholder)
        if placeholder_counts[placeholder] < 0:
            raise ValueError(f"Found more '{placeholder}' placeholders in input prompt than actual multimodal data items.")
        missing_placeholders.extend([placeholder] * placeholder_counts[placeholder])
    return '\n'.join(missing_placeholders + [text_prompt])
_TextParser = partial(cast, ChatCompletionContentPartTextParam)
_ImageParser = partial(cast, ChatCompletionContentPartImageParam)
_AudioParser = partial(cast, ChatCompletionContentPartAudioParam)
_RefusalParser = partial(cast, ChatCompletionContentPartRefusalParam)
MODEL_KEEP_MULTI_MODAL_CONTENT = {'mllama'}

def _parse_chat_message_content_parts(role: str, parts: Iterable[ChatCompletionContentPartParam], mm_tracker: BaseMultiModalItemTracker) -> List[ConversationMessage]:
    texts: List[str] = []
    mm_parser = mm_tracker.create_parser()
    keep_multimodal_content = mm_tracker._model_config.hf_config.model_type in MODEL_KEEP_MULTI_MODAL_CONTENT
    has_image = False
    for part in parts:
        part_type = part['type']
        if part_type == 'text':
            text = _TextParser(part)['text']
            texts.append(text)
        elif part_type == 'image_url':
            image_url = _ImageParser(part)['image_url']
            if image_url.get('detail', 'auto') != 'auto':
                logger.warning("'image_url.detail' is currently not supported and will be ignored.")
            mm_parser.parse_image(image_url['url'])
            has_image = True
        elif part_type == 'audio_url':
            audio_url = _AudioParser(part)['audio_url']
            mm_parser.parse_audio(audio_url['url'])
        elif part_type == 'refusal':
            text = _RefusalParser(part)['refusal']
            texts.append(text)
        else:
            raise NotImplementedError(f'Unknown part type: {part_type}')
    text_prompt = '\n'.join(texts)
    if keep_multimodal_content:
        text_prompt = '\n'.join(texts)
        role_content = [{'type': 'text', 'text': text_prompt}]
        if has_image:
            role_content = [{'type': 'image'}] + role_content
        return [ConversationMessage(role=role, content=role_content)]
    else:
        mm_placeholder_counts = mm_parser.mm_placeholder_counts()
        if mm_placeholder_counts:
            text_prompt = _get_full_multimodal_text_prompt(mm_placeholder_counts, text_prompt)
        return [ConversationMessage(role=role, content=text_prompt)]
_AssistantParser = partial(cast, ChatCompletionAssistantMessageParam)
_ToolParser = partial(cast, ChatCompletionToolMessageParam)

def _parse_chat_message_content(message: ChatCompletionMessageParam, mm_tracker: BaseMultiModalItemTracker) -> List[ConversationMessage]:
    role = message['role']
    content = message.get('content')
    if content is None:
        content = []
    elif isinstance(content, str):
        content = [ChatCompletionContentPartTextParam(type='text', text=content)]
    result = _parse_chat_message_content_parts(role, content, mm_tracker)
    for result_msg in result:
        if role == 'assistant':
            parsed_msg = _AssistantParser(message)
            if 'tool_calls' in parsed_msg:
                result_msg['tool_calls'] = list(parsed_msg['tool_calls'])
        elif role == 'tool':
            parsed_msg = _ToolParser(message)
            if 'tool_call_id' in parsed_msg:
                result_msg['tool_call_id'] = parsed_msg['tool_call_id']
        if 'name' in message and isinstance(message['name'], str):
            result_msg['name'] = message['name']
    return result

def _postprocess_messages(messages: List[ConversationMessage]) -> None:
    for message in messages:
        if message['role'] == 'assistant' and 'tool_calls' in message and isinstance(message['tool_calls'], list):
            for item in message['tool_calls']:
                item['function']['arguments'] = json.loads(item['function']['arguments'])

def parse_chat_messages(messages: List[ChatCompletionMessageParam], model_config: ModelConfig, tokenizer: AnyTokenizer) -> Tuple[List[ConversationMessage], Optional[MultiModalDataDict]]:
    conversation: List[ConversationMessage] = []
    mm_tracker = MultiModalItemTracker(model_config, tokenizer)
    for msg in messages:
        sub_messages = _parse_chat_message_content(msg, mm_tracker)
        conversation.extend(sub_messages)
    _postprocess_messages(conversation)
    return (conversation, mm_tracker.all_mm_data())

def parse_chat_messages_futures(messages: List[ChatCompletionMessageParam], model_config: ModelConfig, tokenizer: AnyTokenizer) -> Tuple[List[ConversationMessage], Awaitable[Optional[MultiModalDataDict]]]:
    conversation: List[ConversationMessage] = []
    mm_tracker = AsyncMultiModalItemTracker(model_config, tokenizer)
    for msg in messages:
        sub_messages = _parse_chat_message_content(msg, mm_tracker)
        conversation.extend(sub_messages)
    _postprocess_messages(conversation)
    return (conversation, mm_tracker.all_mm_data())

def apply_hf_chat_template(tokenizer: Union[PreTrainedTokenizer, PreTrainedTokenizerFast], conversation: List[ConversationMessage], chat_template: Optional[str], *, tokenize: bool=False, **kwargs: Any) -> str:
    if chat_template is None and tokenizer.chat_template is None:
        raise ValueError('As of transformers v4.44, default chat template is no longer allowed, so you must provide a chat template if the tokenizer does not define one.')
    return tokenizer.apply_chat_template(conversation=conversation, chat_template=chat_template, tokenize=tokenize, **kwargs)

def apply_mistral_chat_template(tokenizer: MistralTokenizer, messages: List[ChatCompletionMessageParam], chat_template: Optional[str]=None, **kwargs: Any) -> List[int]:
    if chat_template is not None:
        logger.warning("'chat_template' cannot be overridden for mistral tokenizer.")
    return tokenizer.apply_chat_template(messages=messages, **kwargs)

