        with start_active_span(opname, tracer=tracer):
            yield

    def _decorator(func: Callable[P, R]) -> Callable[P, R]:
        if not opentracing:
            return func
        return _custom_sync_async_decorator(func, _wrapping_logic)
    return _decorator

