    allow_db_access = False
    'For pytests to create/prepare stuff where explicit DB access it needed'

    def __init__(self):
        self.current_db_session = TracebackSessionForTests.db_session_class()
        self.created_traceback = traceback.extract_stack()

    def __getattr__(self, item):
        test_code, frame_summary = self.is_called_from_test_code()
        if self.allow_db_access or test_code:
            return getattr(self.current_db_session, item)
        raise RuntimeError(f"TracebackSessionForTests object was used but internal API is enabled. Only test code is allowed to use this object.\nCalled from:\n    {frame_summary.filename}: {frame_summary.lineno}\n     {frame_summary.line}\n\nYou'll need to ensure you are making only RPC calls with this object. The stack list below will show where the TracebackSession object was called:\n" + get_cleaned_traceback(self.traceback) + '\n\nThe stack list below will show where the TracebackSession object was created:\n' + get_cleaned_traceback(self.created_traceback))

    def remove(*args, **kwargs):
        pass

    @staticmethod
    def set_allow_db_access(session, flag: bool):
        if isinstance(session, TracebackSessionForTests):
            session.allow_db_access = flag

    def is_called_from_test_code(self) -> tuple[bool, traceback.FrameSummary | None]:
        self.traceback = traceback.extract_stack()
        airflow_frames = [tb for tb in self.traceback if tb.filename.startswith(AIRFLOW_PATH) and (not tb.filename == AIRFLOW_SETTINGS_PATH) and (not tb.filename == AIRFLOW_UTILS_SESSION_PATH)]
        if any((filename.endswith('conftest.py') or filename.endswith('tests/test_utils/db.py') for filename, _, _, _ in airflow_frames)):
            return (True, None)
        if len(airflow_frames) >= 2 and airflow_frames[-2].filename.startswith(AIRFLOW_TESTS_PATH) and (airflow_frames[-1].filename == AIRFLOW_MODELS_BASEOPERATOR_PATH) and (airflow_frames[-1].name == 'run'):
            return (True, None)
        for tb in airflow_frames[::-1]:
            if tb.filename.startswith(AIRFLOW_PATH):
                if tb.filename.startswith(AIRFLOW_TESTS_PATH):
                    return (True, None)
                else:
                    return (False, tb)
        return (False, self.traceback[-2])

