def check_referer(func):
    if config.WEB_ALLOWED_REFERERS is False:
        return func

    def _die(referer):
        utils.LOGGER.critical('Invalid Referer header [%r]', referer)
        response.set_header('Content-Type', 'application/javascript')
        response.status = '400 Bad Request'
        return webutils.js_alert('referer', 'error', 'Invalid Referer header. Check your configuration.')

    @wraps(func)
    def _newfunc(*args, **kargs):
        if request.headers.get('X-API-Key') or (request.headers.get('Authorization') and request.headers.get('Authorization', '').split(None, 1)[0].lower() == 'bearer'):
            return func(*args, **kargs)
        referer = request.headers.get('Referer')
        if not referer:
            return _die(referer)
        if config.WEB_ALLOWED_REFERERS is None:
            base_url = '/'.join(request.url.split('/', 3)[:3]) + '/'
            if referer.startswith(base_url):
                return func(*args, **kargs)
